/** Hint-preserving font instances and bounded native font-cache demonstrations. */
export async function createFontFidelityScenes(S,{loadBytes=async url=>{const r=await fetch(url);if(!r.ok)throw new Error(`Font load failed: ${r.status}`);return new Uint8Array(await r.arrayBuffer());}}={}){
 const hint=S.SKTypeface.FromData(await loadBytes('fonts/HintVariable.otf')),variable=S.SKTypeface.FromData(await loadBytes('fonts/RobotoFlex-Variable.woff2'));
 if(!hint||!variable){hint?.Dispose();variable?.Dispose();throw new Error('Font fidelity fixtures could not be decoded.');}
 const draw=fn=>(c,w,h,o={})=>{const owned=[],own=v=>(owned.push(v),v),paint=color=>own(new S.SKPaint({Color:S.SKColor.Parse(color),IsAntialias:true})),label=(text,x,y,size=16,color='#A6BDD1')=>c.DrawText(text,x,y,own(new S.SKFont(null,size)),paint(color)),saved=c.Save();try{c.Scale(w/960,h/600);fn(c,o,own,paint,label);}finally{c.RestoreToCount(saved);for(const item of owned.reverse())item?.Dispose();}};
 const scenes=[
  {id:'font-hints',group:'Fonts & text',title:'Native hint fidelity',tag:'CFF2 · Stem hints · Native pixels',description:'Native CFF2 and CFF1 document instances retain the same stem, hint-mask and counter-mask programs.',code:'const face = hintedFont.Clone([{ Axis: "wght", Value: 700 }]);\nconst font = new SKFont(face, 16);\nfont.Hinting = SKFontHinting.Full;\nfont.ForceAutoHinting = false;\nfont.BaselineSnap = true;\nconst documentBytes = face.GetDocumentFontData();',draw:draw((c,o,own,p,label)=>{
   const weight=Math.min(900,Math.max(100,Math.round(o.weight??500))),face=own(hint.Clone({VariationDesignPosition:{wght:weight}})),document=own(S.SKTypeface.FromData(face.GetDocumentFontData()));
   label('NATIVE HINT PROGRAMS / CFF2 + CFF1',48,56,14);label(`Weight ${weight} · original hint instructions preserved`,48,105,24,'#E7F4F8');
   for(const [i,size]of [9,13,20].entries()){const x=60+i*300;for(const [row,typeface]of [face,document].entries()){const raster=own(S.SKSurface.Create(new S.SKImageInfo(56,40))),font=own(new S.SKFont(typeface,size));font.Edging=S.SKFontEdging.Alias;font.Hinting=S.SKFontHinting.Full;raster.Canvas.Clear(S.SKColor.Parse('#132B39'));raster.Canvas.DrawText('HHH',3,28,font,p(row?'#D4A3FF':'#30DEAB'));raster.Flush();const image=own(raster.Snapshot()),imagePaint=p('#FFFFFF');imagePaint.FilterQuality=S.SKFilterQuality.None;c.DrawImage(image,S.SKRect.Create(x,155+row*142,224,128),imagePaint);}label(`${size} px / magnified ×4`,x,465,16);}
   label('Native CFF2',48,515,18,'#30DEAB');label('Document CFF1',290,515,18,'#D4A3FF');label('Both rows preserve the original stem, hint-mask and counter-mask operators.',48,560,15);
  })},
  {id:'font-cache',group:'Fonts & text',title:'Font cache & ownership',tag:'Bounded cache · Reusable instances',description:'Repeated axes reuse parsed font data and native typefaces. Every returned object is independently disposable.',code:'const args = new SKFontArguments()\n  .SetVariationDesignPosition({ wght: 750 });\nconst first = typeface.Clone(args);\nconst second = typeface.Clone(args);\nfirst.Dispose(); // second remains valid\nconst stats = SKFontCache.GetStatistics();',draw:draw((c,o,own,p,label)=>{
   label('FONT INSTANCING / REUSE AND LIFETIME',48,56,14);[250,550,850].forEach((weight,i)=>{const face=own(variable.Clone({VariationDesignPosition:{wght:weight}})),font=own(new S.SKFont(face,48));c.DrawText('Same source. New weight.',48,155+i*87,font,p(['#30DEAB','#70CBEF','#D4A3FF'][i]));label(`wght ${weight}`,680,155+i*87,17);});
   const stats=S.SKFontCache.GetStatistics(),rows=[['Instance hits',stats.InstanceHits],['Native typeface reuse',stats.NativeHits],['Retained font bytes',stats.RetainedBytes.toLocaleString()],['Cache budget',`${Math.round(stats.MaxBytes/1048576)} MiB`]];rows.forEach(([name,value],i)=>{const x=48+(i%2)*450,y=455+Math.floor(i/2)*75;label(name,x,y,16);label(String(value),x+230,y,19,'#E7F4F8');});
  })}
 ];
 return {scenes,Dispose(){hint.Dispose();variable.Dispose();}};
}
